    Write-Host "  [Dry-run] 略過驗證" -ForegroundColor DarkGray
}

# ───────── 6. 寫還原便條到 E 槽 ─────────
Write-Host "`n[6/6] 寫升級便條..." -ForegroundColor Yellow
